  "recovered_c": "#include <stdint.h>\n#include <stddef.h>\n\nuint64_t fn_07(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint32_t uVar5 = 0;\n  size_t lVar7 = 0;\n  uint8_t bVar1;\n  uint32_t uVar4;\n  uint32_t uVar6;\n  uint8_t cVar2;\n\n  if (out_cap < (len + 2) / 3 << 2) {\n    return VERA_ERR;\n  }\n  if (len < 3) {\n    uVar5 = 0;\n    lVar7 = 0;\n  }\n  else {\n    lVar7 = 0;\n    uVar5 = 3;\n    do {\n      bVar1 = in[uVar5 - 3];\n      lVar7 += 4;\n      uVar4 = (uint32_t)bVar1 << 0x10 | (uint32_t)in[uVar5 - 2] << 8;\n      uVar6 = (uint32_t)in[uVar5 - 1];\n      out[lVar7 - 4] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[uVar6 & 0x3f];\n      out[lVar7 - 4 + 1] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(uVar6 | uVar4) >> 6 & 0x3f];\n      out[lVar7 - 4 + 2] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[uVar4 >> 0xc & 0x3f];\n      out[lVar7 - 4 + 3] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[bVar1 >> 2];\n      uVar5 += 3;\n    } while (uVar5 + 3 <= len);\n    len -= uVar5;\n  }\n  if (len != 1) {\n    if (len != 2) {\n      return lVar7;\n    }\n    uVar4 = (uint32_t)in[uVar5 + 1] << 8;\n    cVar2 = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(uVar4 & 0xf00) >> 6];\n    out[lVar7] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(uVar4 | (uint32_t)in[uVar5] << 0x10) >> 0xc & 0x3f];\n    out[lVar7 + 1] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[in[uVar5] >> 2];\n    out[lVar7 + 2] = cVar2;\n    out[lVar7 + 3] = 0x3d;\n    return lVar7 + 4;\n  }\n  out[lVar7] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(in[uVar5] & 3) << 4];\n  out[lVar7 + 1] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[in[uVar5] >> 2];\n  out[lVar7 + 2] = 0x3d;\n  out[lVar7 + 3] = 0x3d;\n  return lVar7 + 4;\n}\n"
